requirement.mandatory_format:

{
  "type": "BusinessObjectName",
  "description": "Description of the business object",
  "properties": [
    {
      "name": "propertyName",
      "type": "String|Integer|Decimal|Boolean|Date",
      "required": true|false,
      "description": "Property description"
    }
  ]
}

example.file:

{
  "type": "UserData",
  "description": "User profile information",
  "properties": [
    {
      "name": "userId",
      "type": "String",
      "required": true,
      "description": "Unique user identifier"
    },
    {
      "name": "displayName",
      "type": "String",
      "required": true,
      "description": "User's display name"
    },
    {
      "name": "age",
      "type": "Integer",
      "required": false,
      "description": "User's age in years"
    }
  ]
}


{
  "type": "SatisfactionData",
  "description": "Patient satisfaction metrics and analytics",
  "properties": [
    {
      "name": "matricule_patient",
      "type": "String",
      "required": true,
      "description": "Patient matricule (13 digits)"
    },
    {
      "name": "average_satisfaction",
      "type": "Decimal",
      "required": true,
      "description": "Average satisfaction score (1.0-5.0)"
    },
    {
      "name": "total_surveys",
      "type": "Integer",
      "required": true,
      "description": "Total number of surveys sent"
    },
    {
      "name": "lastUpdated",
      "type": "Date",
      "required": true,
      "description": "When data was last updated"
    },
    {
      "name": "satisfactionLevel",
      "type": "String",
      "required": true,
      "description": "Satisfaction level category: excellent, good, fair, poor"
    }
  ]
}

example.wrong_format:

{
  "name": "UserData",              ❌ WRONG: Should be "type"
  "type": "businessObject",        ❌ WRONG: This field should not exist
  "description": "User profile information",
  "properties": [...]
}
